// shutdownHost first closes HTTP ingress, then asks Runtime to stop through its
// normal stdin lifecycle. The bounded calls control responsiveness only. If a
// deadline expires, Host stays alive and repeats the same graceful wait without
// a deadline so the Runtime lease cannot be released by Host process exit while
// the child is still running.
func shutdownHost(
	server httpShutdowner,
	runtime runtimeShutdowner,
	cancelRuntime context.CancelFunc,
	timeout time.Duration,
) error {
	var shutdownErrors []error

	httpCtx, cancelHTTP := context.WithTimeout(context.Background(), timeout)
	httpErr := server.Shutdown(httpCtx)
	cancelHTTP()
	if httpErr != nil && !isShutdownDeadline(httpErr) {
		shutdownErrors = append(shutdownErrors, fmt.Errorf("shutdown HTTP server: %w", httpErr))
	}

	cancelRuntime()
	runtimeCtx, cancelBoundedRuntime := context.WithTimeout(context.Background(), timeout)
	runtimeErr := runtime.Shutdown(runtimeCtx)
	cancelBoundedRuntime()
	if isShutdownDeadline(runtimeErr) {
		runtimeErr = runtime.Shutdown(context.Background())
	}
	if runtimeErr != nil {
		shutdownErrors = append(shutdownErrors, fmt.Errorf("shutdown Codex Runtime: %w", runtimeErr))
	}

	if httpErr != nil {
		if err := server.Shutdown(context.Background()); err != nil {
			shutdownErrors = append(shutdownErrors, fmt.Errorf("finish HTTP server shutdown: %w", err))
		}
	}
	return errors.Join(shutdownErrors...)
}

func (m *Manager) Shutdown(ctx context.Context) (returnErr error) {
	m.mu.Lock()
	m.shutdownRequested = true
	startDone := m.startDone
	startupCancel := m.startupCancel
	started := m.started
	if !started {
		m.status.State = StateStopped
		m.status.Ready = false
		m.status.FailureCode = ""
	}
	m.mu.Unlock()
	if startupCancel != nil {
		startupCancel()
	}
	// Broker admission closes before Runtime EOF. STOP_PENDING is mapped to
	// the existing bounded graceful-wait contract; ownership is retained.
	if err := m.closeMarketBroker(ctx); err != nil {
		if errors.Is(err, marketbroker.ErrStopPending) {
			return context.DeadlineExceeded
		}
		// A reaped worker's unsuccessful exit does not excuse leaving the
		// still-owned Runtime alive. Finish its normal EOF lifecycle as well.
		defer func() { returnErr = errors.Join(returnErr, err) }()
	}
	if started && startDone != nil {
		select {
		case <-startDone:
		case <-ctx.Done():
			return ctx.Err()
		}
	}

	m.mu.Lock()
	state := m.status.State
	if state == StateNotConfigured {
		m.mu.Unlock()
		return nil
	}
	if state == StateStopped {
		cleanupErr := m.authorityCleanupError
		m.mu.Unlock()
		return cleanupErr
	}
	client := m.client
	process := m.cmd
	exitDone := m.exitDone
	alreadyExited := false
	if exitDone != nil {
		select {
		case <-exitDone:
			alreadyExited = true
		default:
		}
	}
	if alreadyExited {
		cleanupErr := m.authorityCleanupError
		if cleanupErr == nil {
			m.status.State = StateStopped
			m.status.Ready = false
			m.status.FailureCode = ""
		}
		m.mu.Unlock()
		return cleanupErr
	}
	m.status.State = StateStopping
	m.status.Ready = false
	m.mu.Unlock()

	if client != nil {
		_ = client.CloseInput()
	}
	if process == nil || exitDone == nil {
		cleanupErr := m.releaseManagedCodexHomeAuthority(true)
		if cleanupErr != nil {
			m.fail("provider_config_failed")
			return cleanupErr
		}
		m.mu.Lock()
		m.status.State = StateStopped
		m.status.Ready = false
		m.status.FailureCode = ""
		m.mu.Unlock()
		return m.managedCodexHomeCleanupError()
	}

	select {
	case <-exitDone:
		return m.managedCodexHomeCleanupError()
	case <-ctx.Done():
		// Keep the lease and exact Runtime rule until waitForExit observes a
		// real process exit. A timeout must not strong-kill Runtime or expose a
		// gate-off Host to a still-running session reloader.
		return ctx.Err()
	}
}

